        $BIN run ../../compiler/stage1/compiler_in_core.lume ../../compiler/stage1/read_line.src <"$ntmp/in2.txt" >"$ntmp/o_i.txt" 2>/dev/null
        cat "$ntmp/in2.txt" | "$ntmp/rl" >"$ntmp/o_n.txt" 2>/dev/null
